result={'plan':plan,'audioTransport':{'passed':True,'exitCode':p.returncode,'frames':frames,'channels':ch,'sampleRate':sr,'engine':engine,'responseSHA256':sha(p.stdout),'PCMHash':sha(y),'bytes':len(y),'wallSeconds':elapsed,'wallTimeNotCallbackLatency':True,'wholeRaw':str((D/'whole-output.f32le').relative_to(R))},'actualCancellation':{'passed':True,'processingEvent':json.loads(line),'aliveBeforeSignal':alive,'exitCode':c.returncode,'partialResponseBytes':len(partial),'partialSHA256':sha(partial),'completedResultAccepted':False,'processGone':c.poll() is not None},'passed':2,'failed':0,'fullParityVerified':False};report.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
